  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.application.notification.*;
  7	import com.pousadamarealta.application.service.ReportService;
  8	import com.pousadamarealta.application.service.ReservationService;
  9	import com.pousadamarealta.domain.event.EventPublisher;
 10	import com.pousadamarealta.domain.event.ReservationCancelledEvent;
 11	import com.pousadamarealta.domain.event.ReservationConfirmedEvent;
 12	import com.pousadamarealta.domain.repository.MessageRepository;
 13	import com.pousadamarealta.domain.repository.ReservationRepository;
 14	import com.pousadamarealta.domain.repository.RoomRepository;
 15	import com.pousadamarealta.infrastructure.http.ReservationController;
 16	import com.pousadamarealta.infrastructure.persistence.DatabaseInitializer;
 17	import com.pousadamarealta.infrastructure.persistence.InMemoryRoomRepository;
 18	import com.pousadamarealta.infrastructure.persistence.PostgresMessageRepository;
 19	import com.pousadamarealta.infrastructure.persistence.PostgresReservationRepository;
 20	import com.zaxxer.hikari.HikariConfig;
 21	import com.zaxxer.hikari.HikariDataSource;
 22	import io.javalin.Javalin;
 23	import io.javalin.json.JavalinJackson;
 24	
 25	import javax.sql.DataSource;
 26	
 27	public class Main {
 28	    public static void main(String[] args) {
 29	        DataSource dataSource = createDataSource();
 30	        DatabaseInitializer.initialize(dataSource);
 31	
 32	        RoomRepository roomRepository = new InMemoryRoomRepository();
 33	        ReservationRepository reservationRepository = new PostgresReservationRepository(dataSource);
 34	        MessageRepository messageRepository = new PostgresMessageRepository(dataSource);
 35	
 36	        EventPublisher eventPublisher = new EventPublisher();
 37	        NotificationService notificationService = new NotificationService(messageRepository);
 38	
 39	        eventPublisher.subscribe(ReservationConfirmedEvent.class,
 40	            new GuestNotificationListener(notificationService, roomRepository));
 41	        eventPublisher.subscribe(ReservationConfirmedEvent.class,
 42	            new HousekeepingNotificationListener(notificationService));
 43	        eventPublisher.subscribe(ReservationConfirmedEvent.class,
 44	            new FinanceNotificationListener(notificationService));
 45	        eventPublisher.subscribe(ReservationCancelledEvent.class,
 46	            new HousekeepingCancellationListener(notificationService));
 47	        eventPublisher.subscribe(ReservationCancelledEvent.class,
 48	            new FinanceCancellationListener(notificationService));
 49	
 50	        ReservationService reservationService = new ReservationService(
 51	            reservationRepository, roomRepository, eventPublisher);
 52	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 53	
 54	        ReservationController controller = new ReservationController(
 55	            reservationService, reportService, roomRepository, messageRepository);
 56	
 57	        ObjectMapper objectMapper = new ObjectMapper()
 58	            .registerModule(new JavaTimeModule())
 59	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 60	
 61	        int port = getPort();
 62	
 63	        Javalin app = Javalin.create(config -> {
 64	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 65	        }).start(port);
 66	
 67	        controller.registerRoutes(app);
 68	
 69	        System.out.println("Pousada Maré Alta system started on port " + port);
 70	    }
 71	
 72	    private static DataSource createDataSource() {
 73	        String jdbcUrl = System.getenv("DB_URL");
 74	        String username = System.getenv("DB_USER");
 75	        String password = System.getenv("DB_PASSWORD");
 76	
 77	        if (jdbcUrl == null) {
 78	            throw new IllegalStateException("DB_URL environment variable not set");
 79	        }
 80	
 81	        HikariConfig config = new HikariConfig();
 82	        config.setJdbcUrl(jdbcUrl);
 83	        config.setUsername(username);
 84	        config.setPassword(password);
 85	        config.setMaximumPoolSize(10);
 86	
 87	        return new HikariDataSource(config);
 88	    }
 89	
 90	    private static int getPort() {
 91	        String portStr = System.getenv("PORT");
 92	        return portStr != null ? Integer.parseInt(portStr) : 7070;
 93	    }
 94	}
 95	package com.pousadamarealta.infrastructure.http;
 96	
 97	import com.pousadamarealta.application.service.*;
 98	import com.pousadamarealta.domain.model.*;
 99	import com.pousadamarealta.domain.repository.MessageRepository;
100	import com.pousadamarealta.domain.repository.RoomRepository;
101	import com.pousadamarealta.infrastructure.http.dto.*;
102	import io.javalin.Javalin;
103	import io.javalin.http.Context;
104	import java.time.LocalDate;
105	import java.time.YearMonth;
106	import java.time.format.DateTimeFormatter;
107	import java.time.format.DateTimeParseException;
108	import java.util.List;
109	
110	public class ReservationController {
111	    private final ReservationService reservationService;
112	    private final ReportService reportService;
113	    private final RoomRepository roomRepository;
114	    private final MessageRepository messageRepository;
115	
116	    public ReservationController(ReservationService reservationService,
117	                                ReportService reportService,
118	                                RoomRepository roomRepository,
119	                                MessageRepository messageRepository) {
120	        this.reservationService = reservationService;
121	        this.reportService = reportService;
122	        this.roomRepository = roomRepository;
123	        this.messageRepository = messageRepository;
124	    }
125	
126	    public void registerRoutes(Javalin app) {
127	        app.get("/rooms", this::getRooms);
128	        app.post("/reservations", this::createReservation);
129	        app.get("/reservations/{id}", this::getReservation);
130	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
131	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
132	        app.post("/reservations/{id}/check-in", this::checkIn);
133	        app.post("/reservations/{id}/check-out", this::checkOut);
134	        app.get("/reservations/{id}/document", this::getDocument);
135	        app.get("/messages", this::getMessages);
136	        app.get("/reports/occupancy", this::getOccupancyReport);
137	        app.get("/reports/revenue", this::getRevenueReport);
138	
139	        app.exception(InvalidRequestException.class, (e, ctx) ->
140	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage())));
141	        app.exception(RoomNotFoundException.class, (e, ctx) ->
142	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage())));
143	        app.exception(ReservationNotFoundException.class, (e, ctx) ->
144	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage())));
145	        app.exception(RoomUnavailableException.class, (e, ctx) ->
146	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage())));
147	        app.exception(OperationNotAllowedException.class, (e, ctx) ->
148	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage())));
149	        app.exception(CapacityExceededException.class, (e, ctx) ->
150	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage())));
151	    }
152	
153	    private void getRooms(Context ctx) {
154	        List<RoomResponse> rooms = roomRepository.findAll().stream()
155	            .map(RoomResponse::from)
156	            .toList();
157	        ctx.json(rooms);
158	    }
159	
160	    private void createReservation(Context ctx) {
161	        try {
162	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
163	
164	            validateRequest(request);
165	
166	            LocalDate checkIn = parseDate(request.checkIn());
167	            LocalDate checkOut = parseDate(request.checkOut());
168	            RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
169	
170	            Reservation reservation = reservationService.createReservation(
171	                request.roomNumber(),
172	                request.guestName(),
173	                request.guestEmail(),
174	                request.guestCpf(),
175	                checkIn,
176	                checkOut,
177	                request.guests(),
178	                ratePlan
179	            );
180	
181	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
182	            ctx.status(201).json(ReservationResponse.from(reservation, room));
183	        } catch (IllegalArgumentException e) {
184	            throw new InvalidRequestException(e.getMessage());
185	        }
186	    }
187	
188	    private void getReservation(Context ctx) {
189	        Long id = Long.parseLong(ctx.pathParam("id"));
190	        Reservation reservation = reservationService.findById(id);
191	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
192	        ctx.json(ReservationResponse.from(reservation, room));
193	    }
194	
195	    private void confirmReservation(Context ctx) {
196	        Long id = Long.parseLong(ctx.pathParam("id"));
197	        Reservation reservation = reservationService.confirmReservation(id);
198	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
199	        ctx.json(ReservationResponse.from(reservation, room));
200	    }
201	
202	    private void cancelReservation(Context ctx) {
203	        Long id = Long.parseLong(ctx.pathParam("id"));
204	        Reservation reservation = reservationService.cancelReservation(id);
205	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
206	        ctx.json(ReservationResponse.from(reservation, room));
207	    }
208	
209	    private void checkIn(Context ctx) {
210	        Long id = Long.parseLong(ctx.pathParam("id"));
211	        Reservation reservation = reservationService.checkIn(id);
212	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
213	        ctx.json(ReservationResponse.from(reservation, room));
214	    }
215	
216	    private void checkOut(Context ctx) {
217	        Long id = Long.parseLong(ctx.pathParam("id"));
218	        Reservation reservation = reservationService.checkOut(id);
219	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
220	        ctx.json(ReceiptResponse.from(reservation, room));
221	    }
222	
223	    private void getDocument(Context ctx) {
224	        Long id = Long.parseLong(ctx.pathParam("id"));
225	        Reservation reservation = reservationService.findById(id);
226	
227	        if (!reservation.isPaid()) {
228	            throw new OperationNotAllowedException("Document only available for paid reservations");
229	        }
230	
231	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
232	        ctx.json(ReceiptResponse.from(reservation, room));
233	    }
234	
235	    private void getMessages(Context ctx) {
236	        List<MessageResponse> messages = messageRepository.findAll().stream()
237	            .map(MessageResponse::from)
238	            .toList();
239	        ctx.json(messages);
240	    }
241	
242	    private void getOccupancyReport(Context ctx) {
243	        String dateStr = ctx.queryParam("date");
244	        if (dateStr == null) {
245	            throw new InvalidRequestException("Missing 'date' parameter");
246	        }
247	
248	        LocalDate date = parseDate(dateStr);
249	        String csv = reportService.generateOccupancyReport(date);
250	        ctx.contentType("text/csv; charset=utf-8").result(csv);
251	    }
252	
253	    private void getRevenueReport(Context ctx) {
254	        String monthStr = ctx.queryParam("month");
255	        if (monthStr == null) {
256	            throw new InvalidRequestException("Missing 'month' parameter");
257	        }
258	
259	        YearMonth month = parseMonth(monthStr);
260	        String csv = reportService.generateRevenueReport(month);
261	        ctx.contentType("text/csv; charset=utf-8").result(csv);
262	    }
263	
264	    private void validateRequest(CreateReservationRequest request) {
265	        if (request.roomNumber() == null || request.guestName() == null ||
266	            request.guestEmail() == null || request.guestCpf() == null ||
267	            request.checkIn() == null || request.checkOut() == null ||
268	            request.guests() == null || request.ratePlan() == null) {
269	            throw new InvalidRequestException("Missing required fields");
270	        }
271	    }
272	
273	    private LocalDate parseDate(String dateStr) {
274	        try {
275	            return LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
276	        } catch (DateTimeParseException e) {
277	            throw new InvalidRequestException("Invalid date format");
278	        }
279	    }
280	
281	    private YearMonth parseMonth(String monthStr) {
282	        try {
283	            return YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
284	        } catch (DateTimeParseException e) {
285	            throw new InvalidRequestException("Invalid month format");
286	        }
287	    }
288	}

