113	package com.pousadamarealta.application.service;
114	
115	import com.pousadamarealta.domain.model.Reservation;
116	import com.pousadamarealta.domain.model.Room;
117	import com.pousadamarealta.domain.repository.ReservationRepository;
118	import com.pousadamarealta.domain.repository.RoomRepository;
119	import java.math.BigDecimal;
120	import java.time.LocalDate;
121	import java.time.YearMonth;
122	import java.time.format.DateTimeFormatter;
123	import java.util.List;
124	import java.util.Locale;
125	import java.util.stream.Collectors;
126	
127	public class ReportService {
128	    private final ReservationRepository reservationRepository;
129	    private final RoomRepository roomRepository;
130	    private static final DateTimeFormatter CSV_DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
131	
132	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
133	        this.reservationRepository = reservationRepository;
134	        this.roomRepository = roomRepository;
135	    }
136	
137	    public String generateOccupancyReport(LocalDate date) {
138	        List<Reservation> occupiedReservations = reservationRepository.findPaidByDate(date);
139	        List<Room> allRooms = roomRepository.findAll();
140	
141	        StringBuilder csv = new StringBuilder();
142	        csv.append("room,type,reservation,check_in,check_out\n");
143	
144	        for (Reservation reservation : occupiedReservations) {
145	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
146	            csv.append(String.format("%s,%s,%d,%s,%s\n",
147	                reservation.getRoomNumber(),
148	                room.getType().name(),
149	                reservation.getId(),
150	                reservation.getCheckIn().format(CSV_DATE_FORMATTER),
151	                reservation.getCheckOut().format(CSV_DATE_FORMATTER)));
152	        }
153	
154	        csv.append(String.format("total,%d/%d", occupiedReservations.size(), allRooms.size()));
155	
156	        return csv.toString();
157	    }
158	
159	    public String generateRevenueReport(YearMonth month) {
160	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(
161	            month.getYear(), month.getMonthValue());
162	
163	        StringBuilder csv = new StringBuilder();
164	        csv.append("reservation,room,check_in,check_out,status,amount\n");
165	
166	        BigDecimal total = BigDecimal.ZERO;
167	
168	        for (Reservation reservation : reservations) {
169	            BigDecimal amount = calculateRevenue(reservation);
170	            if (amount.compareTo(BigDecimal.ZERO) > 0) {
171	                csv.append(String.format(Locale.US, "%d,%s,%s,%s,%s,%.2f\n",
172	                    reservation.getId(),
173	                    reservation.getRoomNumber(),
174	                    reservation.getCheckIn().format(CSV_DATE_FORMATTER),
175	                    reservation.getCheckOut().format(CSV_DATE_FORMATTER),
176	                    reservation.getStatus().name(),
177	                    amount));
178	                total = total.add(amount);
179	            }
180	        }
181	
182	        csv.append(String.format(Locale.US, "total,%.2f", total));
183	
184	        return csv.toString();
185	    }
186	
187	    private BigDecimal calculateRevenue(Reservation reservation) {
188	        BigDecimal paid = reservation.getAmountPaid();
189	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
190	        return paid.subtract(refunded);
191	    }
192	}
193	package com.pousadamarealta.domain.model;
194	
195	import java.math.BigDecimal;
196	import java.math.RoundingMode;
197	import java.time.LocalDate;
198	import java.time.Month;
199	
200	public class Reservation {
201	    private Long id;
202	    private final String roomNumber;
203	    private final String guestName;
204	    private final String guestEmail;
205	    private final String guestCpf;
206	    private final LocalDate checkIn;
207	    private final LocalDate checkOut;
208	    private final int guests;
209	    private final RatePlan ratePlan;
210	    private ReservationStatus status;
211	    private BigDecimal amountPaid;
212	    private BigDecimal refund;
213	
214	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
215	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
216	                      ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
217	        this.id = id;
218	        this.roomNumber = roomNumber;
219	        this.guestName = guestName;
220	        this.guestEmail = guestEmail;
221	        this.guestCpf = guestCpf;
222	        this.checkIn = checkIn;
223	        this.checkOut = checkOut;
224	        this.guests = guests;
225	        this.ratePlan = ratePlan;
226	        this.status = status;
227	        this.amountPaid = amountPaid != null ? amountPaid : BigDecimal.ZERO;
228	        this.refund = refund;
229	    }
230	
231	    public static Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
232	                                    LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
233	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf,
234	                             checkIn, checkOut, guests, ratePlan,
235	                             ReservationStatus.PENDING, BigDecimal.ZERO, null);
236	    }
237	
238	    public void setId(Long id) {
239	        this.id = id;
240	    }
241	
242	    public Long getId() {
243	        return id;
244	    }
245	
246	    public String getRoomNumber() {
247	        return roomNumber;
248	    }
249	
250	    public String getGuestName() {
251	        return guestName;
252	    }
253	
254	    public String getGuestEmail() {
255	        return guestEmail;
256	    }
257	
258	    public String getGuestCpf() {
259	        return guestCpf;
260	    }
261	
262	    public LocalDate getCheckIn() {
263	        return checkIn;
264	    }
265	
266	    public LocalDate getCheckOut() {
267	        return checkOut;
268	    }
269	
270	    public int getGuests() {
271	        return guests;
272	    }
273	
274	    public RatePlan getRatePlan() {
275	        return ratePlan;
276	    }
277	
278	    public ReservationStatus getStatus() {
279	        return status;
280	    }
281	
282	    public BigDecimal getAmountPaid() {
283	        return amountPaid;
284	    }
285	
286	    public BigDecimal getRefund() {
287	        return refund;
288	    }
289	
290	    public int getNights() {
291	        return (int) checkIn.until(checkOut).getDays();
292	    }
293	
294	    public BigDecimal calculateSubtotal(Room room) {
295	        BigDecimal subtotal = BigDecimal.ZERO;
296	        LocalDate date = checkIn;
297	
298	        while (date.isBefore(checkOut)) {
299	            BigDecimal nightRate = room.getNightlyRate();
300	            if (isHighSeason(date)) {
301	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
302	                                    .setScale(2, RoundingMode.HALF_EVEN);
303	            }
304	            subtotal = subtotal.add(nightRate);
305	            date = date.plusDays(1);
306	        }
307	
308	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
309	    }
310	
311	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
312	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
313	            return subtotal.multiply(new BigDecimal("0.15"))
314	                          .setScale(2, RoundingMode.HALF_EVEN);
315	        }
316	        return BigDecimal.ZERO;
317	    }
318	
319	    public BigDecimal calculateTotal(Room room) {
320	        BigDecimal subtotal = calculateSubtotal(room);
321	        BigDecimal discount = calculateDiscount(subtotal);
322	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
323	    }
324	
325	    private boolean isHighSeason(LocalDate date) {
326	        Month month = date.getMonth();
327	        int day = date.getDayOfMonth();
328	
329	        if (month == Month.JULY) {
330	            return true;
331	        }
332	
333	        if (month == Month.DECEMBER && day >= 15) {
334	            return true;
335	        }
336	
337	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
338	            return true;
339	        }
340	
341	        return false;
342	    }
343	
344	    public void confirm(BigDecimal amount) {
345	        if (status != ReservationStatus.PENDING) {
346	            throw new IllegalStateException("Only PENDING reservations can be confirmed");
347	        }
348	        this.status = ReservationStatus.CONFIRMED;
349	        this.amountPaid = amount;
350	    }
351	
352	    public void checkIn() {
353	        if (status != ReservationStatus.CONFIRMED) {
354	            throw new IllegalStateException("Only CONFIRMED reservations can be checked in");
355	        }
356	        this.status = ReservationStatus.CHECKED_IN;
357	    }
358	
359	    public void checkOut() {
360	        if (status != ReservationStatus.CHECKED_IN) {
361	            throw new IllegalStateException("Only CHECKED_IN reservations can be checked out");
362	        }
363	        this.status = ReservationStatus.CHECKED_OUT;
364	    }
365	
366	    public BigDecimal cancel() {
367	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
368	            throw new IllegalStateException("Only PENDING or CONFIRMED reservations can be cancelled");
369	        }
370	
371	        this.status = ReservationStatus.CANCELLED;
372	
373	        if (ratePlan == RatePlan.STANDARD) {
374	            this.refund = amountPaid;
375	            return amountPaid;
376	        } else {
377	            this.refund = BigDecimal.ZERO;
378	            return BigDecimal.ZERO;
379	        }
380	    }
381	
382	    public boolean isPaid() {
383	        return status == ReservationStatus.CONFIRMED
384	            || status == ReservationStatus.CHECKED_IN
385	            || status == ReservationStatus.CHECKED_OUT;
386	    }
387	}

