272	    }
273	
274	    public RatePlan getRatePlan() {
275	        return ratePlan;
276	    }
277	
278	    public ReservationStatus getStatus() {
279	        return status;
280	    }
281	
282	    public BigDecimal getAmountPaid() {
283	        return amountPaid;
284	    }
285	
286	    public BigDecimal getRefund() {
287	        return refund;
288	    }
289	
290	    public int getNights() {
291	        return (int) checkIn.until(checkOut).getDays();
292	    }
293	
294	    public BigDecimal calculateSubtotal(Room room) {
295	        BigDecimal subtotal = BigDecimal.ZERO;
296	        LocalDate date = checkIn;
297	
298	        while (date.isBefore(checkOut)) {
299	            BigDecimal nightRate = room.getNightlyRate();
300	            if (isHighSeason(date)) {
301	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
302	                                    .setScale(2, RoundingMode.HALF_EVEN);
303	            }
304	            subtotal = subtotal.add(nightRate);
305	            date = date.plusDays(1);
306	        }
307	
308	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
309	    }
310	
311	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
312	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
313	            return subtotal.multiply(new BigDecimal("0.15"))
314	                          .setScale(2, RoundingMode.HALF_EVEN);
315	        }
316	        return BigDecimal.ZERO;
317	    }
318	
319	    public BigDecimal calculateTotal(Room room) {
320	        BigDecimal subtotal = calculateSubtotal(room);
321	        BigDecimal discount = calculateDiscount(subtotal);
322	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
323	    }
324	
325	    private boolean isHighSeason(LocalDate date) {
326	        Month month = date.getMonth();
327	        int day = date.getDayOfMonth();
328	
329	        if (month == Month.JULY) {
330	            return true;
331	        }
332	
333	        if (month == Month.DECEMBER && day >= 15) {
334	            return true;
335	        }
336	
337	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
338	            return true;
339	        }
340	
341	        return false;
342	    }
343	
344	    public void confirm(BigDecimal amount) {
345	        if (status != ReservationStatus.PENDING) {
346	            throw new IllegalStateException("Only PENDING reservations can be confirmed");
347	        }
348	        this.status = ReservationStatus.CONFIRMED;
349	        this.amountPaid = amount;
350	    }
351	
352	    public void checkIn() {
353	        if (status != ReservationStatus.CONFIRMED) {
354	            throw new IllegalStateException("Only CONFIRMED reservations can be checked in");
355	        }
356	        this.status = ReservationStatus.CHECKED_IN;
357	    }
358	
359	    public void checkOut() {
360	        if (status != ReservationStatus.CHECKED_IN) {
361	            throw new IllegalStateException("Only CHECKED_IN reservations can be checked out");
362	        }
363	        this.status = ReservationStatus.CHECKED_OUT;
364	    }
365	
366	    public BigDecimal cancel() {
367	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
368	            throw new IllegalStateException("Only PENDING or CONFIRMED reservations can be cancelled");
369	        }
370	
371	        this.status = ReservationStatus.CANCELLED;
372	
373	        if (ratePlan == RatePlan.STANDARD) {
374	            this.refund = amountPaid;
375	            return amountPaid;
376	        } else {
377	            this.refund = BigDecimal.ZERO;
378	            return BigDecimal.ZERO;
379	        }
380	    }
381	
382	    public boolean isPaid() {
383	        return status == ReservationStatus.CONFIRMED
384	            || status == ReservationStatus.CHECKED_IN
385	            || status == ReservationStatus.CHECKED_OUT;
386	    }
387	}

