     8	public class EventPublisher {
     9	    private final Map<Class<? extends DomainEvent>, List<EventListener<? extends DomainEvent>>> listeners = new HashMap<>();
    10	
    11	    public <T extends DomainEvent> void subscribe(Class<T> eventType, EventListener<T> listener) {
    12	        listeners.computeIfAbsent(eventType, k -> new ArrayList<>()).add(listener);
    13	    }
