    16	        List<EventListener<? extends DomainEvent>> eventListeners = listeners.get(event.getClass());
    17	        if (eventListeners != null) {
    18	            for (EventListener<? extends DomainEvent> listener : eventListeners) {
    19	                @SuppressWarnings("unchecked")
    20	                EventListener<T> typedListener = (EventListener<T>) listener;
    21	                typedListener.handle(event);
    22	            }
    23	        }
    24	    }
    25	}
