     8	import java.math.BigDecimal;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.Locale;
    11	
    12	public class GuestNotificationListener implements EventListener<ReservationConfirmedEvent> {
    13	    private final NotificationService notificationService;
    14	    private final RoomRepository roomRepository;
    15	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    16	    private static final Locale BR_LOCALE = new Locale("pt", "BR");
    17	
    18	    public GuestNotificationListener(NotificationService notificationService, RoomRepository roomRepository) {
    19	        this.notificationService = notificationService;
    20	        this.roomRepository = roomRepository;
    21	    }
    22	
    23	    @Override
    24	    public void handle(ReservationConfirmedEvent event) {
    25	        Reservation reservation = event.reservation();
    26	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    27	
    28	        String subject = "Reserva confirmada - Pousada Maré Alta";
    29	        String body = buildEmailBody(reservation, room);
    30	
    31	        notificationService.sendEmail(reservation.getGuestEmail(), subject, body);
    32	    }
    33	
    34	    private String buildEmailBody(Reservation reservation, Room room) {
    35	        StringBuilder sb = new StringBuilder();
    36	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
    37	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
    38	        sb.append(buildReceipt(reservation, room));
    39	        sb.append("\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
    40	        sb.append("Até breve!");
    41	        return sb.toString();
    42	    }
    43	
    44	    private String buildReceipt(Reservation reservation, Room room) {
    45	        StringBuilder sb = new StringBuilder();
    46	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    47	        sb.append("Hóspede: ").append(reservation.getGuestName())
    48	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    49	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    50	          .append(" (").append(room.getType()).append(")\n");
    51	        sb.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
    52	          .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
    53	          .append(" | ").append(reservation.getNights()).append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    54	
    55	        BigDecimal subtotal = reservation.calculateSubtotal(room);
    56	        BigDecimal discount = reservation.calculateDiscount(subtotal);
    57	        BigDecimal total = reservation.calculateTotal(room);
    58	
    59	        sb.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
    60	
    61	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
    62	            sb.append("Desconto: ").append(formatMoney(discount)).append("\n");
    63	        }
    64	
    65	        sb.append("Total: ").append(formatMoney(total));
    66	
    67	        return sb.toString();
    68	    }
    69	
    70	    private String formatCpf(String cpf) {
    71	        return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
    72	    }
    73	
    74	    private String formatMoney(BigDecimal amount) {
    75	        return String.format(BR_LOCALE, "R$ %,.2f", amount);
    76	    }
    77	}
