    30	    private Reservation insert(Reservation reservation) {
    31	        String sql = """
    32	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
    33	                                     check_in, check_out, guests, rate_plan, status, amount_paid, refund)
    34	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    35	            RETURNING id
    36	        """;
