    38	        try (Connection conn = dataSource.getConnection();
    39	             PreparedStatement stmt = conn.prepareStatement(sql)) {
    40	
    41	            stmt.setString(1, reservation.getRoomNumber());
    42	            stmt.setString(2, reservation.getGuestName());
    43	            stmt.setString(3, reservation.getGuestEmail());
