    50	            stmt.setBigDecimal(10, reservation.getAmountPaid());
    51	            stmt.setBigDecimal(11, reservation.getRefund());
    52	
    53	            ResultSet rs = stmt.executeQuery();
    54	            if (rs.next()) {
    55	                reservation.setId(rs.getLong("id"));
    56	            }
    57	
    58	            return reservation;
    59	        } catch (SQLException e) {
    60	            throw new RuntimeException("Failed to insert reservation", e);
    61	        }
    62	    }
    63	
    64	    private Reservation update(Reservation reservation) {
    65	        String sql = """
    66	            UPDATE reservations
    67	            SET status = ?, amount_paid = ?, refund = ?
    68	            WHERE id = ?
    69	        """;
    70	
    71	        try (Connection conn = dataSource.getConnection();
    72	             PreparedStatement stmt = conn.prepareStatement(sql)) {
    73	
    74	            stmt.setString(1, reservation.getStatus().name());
    75	            stmt.setBigDecimal(2, reservation.getAmountPaid());
    76	            stmt.setBigDecimal(3, reservation.getRefund());
    77	            stmt.setLong(4, reservation.getId());
    78	
    79	            stmt.executeUpdate();
    80	            return reservation;
