   110	            AND status != 'CANCELLED'
   111	            AND check_in < ?
   112	            AND check_out > ?
   113	        """;
   114	
   115	        try (Connection conn = dataSource.getConnection();
   116	             PreparedStatement stmt = conn.prepareStatement(sql)) {
