   137	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   138	            AND check_in <= ?
   139	            AND check_out > ?
   140	            ORDER BY room_number
   141	        """;
   142	
   143	        try (Connection conn = dataSource.getConnection();
   144	             PreparedStatement stmt = conn.prepareStatement(sql)) {
