   161	    public List<Reservation> findByCheckInMonth(int year, int month) {
   162	        String sql = """
   163	            SELECT * FROM reservations
   164	            WHERE EXTRACT(YEAR FROM check_in) = ?
   165	            AND EXTRACT(MONTH FROM check_in) = ?
   166	            ORDER BY check_in, id
   167	        """;
   168	
   169	        try (Connection conn = dataSource.getConnection();
   170	             PreparedStatement stmt = conn.prepareStatement(sql)) {
   171	
